Actionscript.script:
stop();
var bounds=content.getBounds(this);
var left=Math.floor(bounds.xMin),top=Math.floor(bounds.yMin);
var width=Math.ceil(bounds.xMax)-left,height=Math.ceil(bounds.yMax)-top;
if(width>0 && height>0 && width<=1024 && height<=512) {
  this.__cf6SkyNoise=new flash.display.BitmapData(width,height,true,0xFF000000);
  this.__cf6SkyNoise.perlinNoise(83.33333333333333,22.22222222222222,3,1595,false,false,1,true,[new flash.geom.Point(left,top),new flash.geom.Point(left,top),new flash.geom.Point(left,top)]);
  this.__cf6SkyNoise.applyFilter(this.__cf6SkyNoise,new flash.geom.Rectangle(0,0,width,height),new flash.geom.Point(0,0),new flash.filters.ColorMatrixFilter([0,0,0,0,241.04560961783594,0,0,0,0,239.83386188152363,0,0,0,0,221.93795799777254,0.2,0,0,0,0]));
  var haze=this.createEmptyMovieClip("nativeHaze",this.getNextHighestDepth());
  haze._x=left;haze._y=top;haze.attachBitmap(this.__cf6SkyNoise,0,"auto",true);
  content.cacheAsBitmap=true;haze.cacheAsBitmap=true;haze.setMask(content);
  this.onUnload=function(){this.__cf6SkyNoise.dispose();};
} else {trace("CF6_SKY_NOISE_BOUNDS_UNSUPPORTED");}
